#include <bits/stdc++.h>
using namespace std;

struct Piece {
    int idx;
    int k;
    vector<pair<int,int>> cells;
};

struct Orientation {
    vector<pair<int,int>> cells;
    int w, h;
};

vector<Orientation> getOrientations(const vector<pair<int,int>>& cells) {
    vector<Orientation> oris;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> tc;
            for (auto [x, y] : cells) {
                int nx = x, ny = y;
                if (f) nx = -nx;
                for (int i = 0; i < r; i++) {
                    int tmp = nx;
                    nx = ny;
                    ny = -tmp;
                }
                tc.push_back({nx, ny});
            }
            // normalize
            int minx = INT_MAX, miny = INT_MAX;
            for (auto [x,y] : tc) { minx = min(minx, x); miny = min(miny, y); }
            for (auto& [x,y] : tc) { x -= minx; y -= miny; }
            sort(tc.begin(), tc.end());
            if (seen.insert(tc).second) {
                int w = 0, h = 0;
                for (auto [x,y] : tc) { w = max(w, x+1); h = max(h, y+1); }
                oris.push_back({tc, w, h});
            }
        }
    }
    return oris;
}

struct PlacementResult {
    int x, y, r, f;
    int oriIdx;
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Piece> pieces(n);
    int totalCells = 0;
    for (int i = 0; i < n; i++) {
        pieces[i].idx = i;
        cin >> pieces[i].k;
        pieces[i].cells.resize(pieces[i].k);
        for (int j = 0; j < pieces[i].k; j++) {
            cin >> pieces[i].cells[j].first >> pieces[i].cells[j].second;
        }
        totalCells += pieces[i].k;
    }

    // Precompute all orientations for each piece (in original order)
    // But also store f,r for output
    struct OriInfo {
        vector<pair<int,int>> cells;
        int w, h;
        int f, r; // the f and r that produce this orientation
    };

    vector<vector<OriInfo>> allOris(n);
    for (int i = 0; i < n; i++) {
        set<vector<pair<int,int>>> seen;
        for (int f = 0; f < 2; f++) {
            for (int r = 0; r < 4; r++) {
                vector<pair<int,int>> tc;
                for (auto [x, y] : pieces[i].cells) {
                    int nx = x, ny = y;
                    if (f) nx = -nx;
                    for (int q = 0; q < r; q++) {
                        int tmp = nx;
                        nx = ny;
                        ny = -tmp;
                    }
                    tc.push_back({nx, ny});
                }
                int minx = INT_MAX, miny = INT_MAX;
                for (auto [x,y] : tc) { minx = min(minx, x); miny = min(miny, y); }
                for (auto& [x,y] : tc) { x -= minx; y -= miny; }
                sort(tc.begin(), tc.end());
                if (seen.insert(tc).second) {
                    int w = 0, h = 0;
                    for (auto [x,y] : tc) { w = max(w, x+1); h = max(h, y+1); }
                    allOris[i].push_back({tc, w, h, f, r});
                }
            }
        }
    }

    // Sort pieces by size descending, then by max dimension descending
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if (pieces[a].k != pieces[b].k) return pieces[a].k > pieces[b].k;
        int maxdA = 0, maxdB = 0;
        for (auto& o : allOris[a]) maxdA = max(maxdA, max(o.w, o.h));
        for (auto& o : allOris[b]) maxdB = max(maxdB, max(o.w, o.h));
        return maxdA > maxdB;
    });

    // Try different widths
    int bestArea = INT_MAX;
    int bestH = INT_MAX, bestW = INT_MAX;
    vector<PlacementResult> bestPlacements(n);

    // Estimate good width range
    double sqrtArea = sqrt((double)totalCells * 1.15);

    // Generate candidate widths
    vector<int> candidateW;
    for (double mult = 0.5; mult <= 3.0; mult += 0.1) {
        int w = max(10, (int)(sqrtArea * mult));
        candidateW.push_back(w);
    }
    // Also add some specific values
    sort(candidateW.begin(), candidateW.end());
    candidateW.erase(unique(candidateW.begin(), candidateW.end()), candidateW.end());

    // Time limit management
    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now() - startTime).count();
    };

    // Limit candidates based on n
    double timeLimit = 9.0;

    for (int W : candidateW) {
        if (elapsed() > timeLimit) break;

        // heightmap: for each column x, the lowest free y
        vector<int> heightmap(W, 0);
        // Grid to track occupied cells
        int maxH = totalCells + 10; // upper bound
        // Use a more memory-efficient approach
        // For large n, we can't have a huge grid. Let's use a set or heightmap-only approach.

        // Actually, for correctness with polyominoes we need to check cell-by-cell.
        // Use a hash set of occupied positions.
        unordered_set<long long> occupied;
        auto encode = [](int x, int y) -> long long { return (long long)x * 100000LL + y; };

        vector<PlacementResult> placements(n);
        int maxY = 0;
        bool failed = false;

        for (int idx = 0; idx < n && !failed; idx++) {
            if (elapsed() > timeLimit) { failed = true; break; }
            int pi = order[idx];

            int bestPlaceScore = INT_MAX;
            int bx = -1, by = -1, boi = -1;

            for (int oi = 0; oi < (int)allOris[pi].size(); oi++) {
                auto& ori = allOris[pi][oi];
                if (ori.w > W) continue;

                for (int x = 0; x <= W - ori.w; x++) {
                    // Find minimum y from heightmap
                    int minY = 0;
                    for (auto [cx, cy] : ori.cells) {
                        minY = max(minY, heightmap[x + cx] - cy);
                    }
                    // Ensure all cells non-negative y
                    for (auto [cx, cy] : ori.cells) {
                        if (minY + cy < 0) minY = -cy; // shouldn't happen since cy >= 0
                    }

                    // Check no overlap
                    bool ok = true;
                    for (auto [cx, cy] : ori.cells) {
                        int px = x + cx, py = minY + cy;
                        if (px < 0 || px >= W || py < 0) { ok = false; break; }
                        if (occupied.count(encode(px, py))) { ok = false; break; }
                    }

                    if (ok) {
                        int topY = 0;
                        for (auto [cx, cy] : ori.cells) topY = max(topY, minY + cy + 1);
                        int score = topY * 1000 + minY;
                        if (score < bestPlaceScore) {
                            bestPlaceScore = score;
                            bx = x; by = minY; boi = oi;
                        }
                    }
                }
            }

            if (bx == -1) { failed = true; break; }

            auto& ori = allOris[pi][boi];
            for (auto [cx, cy] : ori.cells) {
                int px = bx + cx, py = by + cy;
                occupied.insert(encode(px, py));
                heightmap[px] = max(heightmap[px], py + 1);
                maxY = max(maxY, py + 1);
            }

            placements[pi] = {bx, by, ori.r, ori.f, boi};
        }

        if (failed) continue;

        int H = maxY;
        long long area = (long long)W * H;
        if (area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))) {
            bestArea = area;
            bestH = H;
            bestW = W;
            bestPlacements = placements;
        }
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
        cout << bestPlacements[i].x << " " << bestPlacements[i].y << " " 
             << bestPlacements[i].r << " " << bestPlacements[i].f << "\n";
    }

    return 0;
}
